from collections import Counter

def find_magic():
    x = [0] * 12
    x[7] = 0
    x[8] = 1
    def bt(pos, rem):
        if pos == 12:
            return rem == 0 and check(x)
        if pos == 7 or pos == 8:  # already set
            return bt(pos + 1, rem - x[pos])
        for v in range(0, rem + 1):
            if v == 7: continue
            x[pos] = v
            if bt(pos + 1, rem - v):
                return True
        x[pos] = 0  # reset
        return False
    def check(x):
        c = Counter(x)
        for i in range(12):
            if c.get(i, 0) != x[i]:
                return False
        return True
    if bt(0, 12):
        return x
    return None

result = find_magic()
print(result)
